        ("$\\tan^{-1}(1/2) + \\tan^{-1}(1/3)$ এর মান কত?", ["\\pi/4", "\\pi/2", "\\pi/3", "\\pi/6"], "A", "$\\tan^{-1}\\left(\\frac{1/2 + 1/3}{1 - (1/2)(1/3)}\\right) = \\tan^{-1}\\left(\\frac{5/6}{5/6}\\right) = \\tan^{-1}(1) = \\frac{\\pi}{4}$।", "ত্রিকোণমিতি", "BUET Admission 2017-18", "EASY"),
        ("$^n P_r = 720$ এবং $^n C_r = 120$ হলে r এর মান কত?", ["3", "4", "5", "6"], "A", "$r! = \\frac{^n P_r}{^n C_r} = \\frac{720}{120} = 6 \\implies r! = 3! \\implies r = 3$।", "বিন্যাস ও সমাবেশ", "BUET Admission 2016-17", "EASY"),
        ("$\\int_0^1 \\frac{1}{1 + x^2} dx$ এর মান কত?", ["\\pi/4", "\\pi/2", "1", "0"], "A", "$[\\tan^{-1} x]_0^1 = \\tan^{-1}(1) - \\tan^{-1}(0) = \\frac{\\pi}{4} - 0 = \\frac{\\pi}{4}$।", "ক্যালকুলাস", "BUET Admission 2023-24", "EASY"),
