def main():
    seeds_dir = Path("backend/app/db/seeds")
    seeds_dir.mkdir(parents=True, exist_ok=True)

    datasets = {
        "nctb_ssc_physics.json": generate_ssc_physics_questions(),
        "nctb_hsc_chemistry.json": generate_hsc_chemistry_questions(),
        "buet_math_admission.json": generate_buet_math_questions(),
        "du_ka_admission.json": generate_du_ka_questions(),
        "medical_admission.json": generate_medical_admission_questions()
    }

    for filename, data in datasets.items():
        filepath = seeds_dir / filename
        with open(filepath, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        print(f"Generated {filename}: {len(data)} items")


if __name__ == "__main__":
    main()
